export const Settings = ({setPressed, pressed, noChat, showEvalBar}) => {
    const {settings, setSettings, typing, isMobile} = useContext (UserContext)     // hook???
    const [opened, setOpened] = useState(false)
    const settingsRef = useRef(null)
    const buttonRef = useRef (null)
    const iconRef = useRef(null)
    useOutsideAlerter(settingsRef, iconRef, null, setOpened)

    const settingsHandler = () => {
        setOpened(prev => !prev)     
    }

    useEffect (() => {
        if (pressed !== 'settings') {
            setOpened(false)
        }
    }, [pressed])

    useEffect (() => {
        if(opened) {
            settingsRef.current.style.bottom = '50px'
            // settingsRef.current.style.height = !noChat? '143px' : '108px' // 182px ?
            settingsRef.current.style.height = '143px'
            setPressed('settings') 
        } else {
            settingsRef.current.style.bottom = '0px'
            settingsRef.current.style.height = '0px'
        }
        if (!buttonRef.current) {return}
        buttonRef.current.style.animation = 'none' 
        buttonRef.current.style.left = '50%'
        buttonRef.current.style.top = '50%'
        requestAnimationFrame(() => {
            buttonRef.current.style.animation = 'ripples-toggle 0.3s ease-in forwards'
        })
    },[opened]) 

    const Switcher = ({flag, lbl}) => {
        const [checked, setChecked] = useState(flag)
        const switchHandler = () => {
            setChecked(prev => !prev)
            // console.log(lbl)
            if (lbl === 'show legal moves') {setSettings(prev=> ({...prev, showLegalMoves: !prev.showLegalMoves}))}
            else if (lbl === 'mark last move') {setSettings(prev=> ({...prev, markLastMove: !prev.markLastMove}))}
            else if (lbl === 'sound') {setSettings(prev=> ({...prev, sound: !prev.sound}))}
            else if (lbl === 'chat') {setSettings(prev=> ({...prev, chat: !prev.chat}))}
            else if (lbl === 'show evaluation bar') {setSettings(prev=> ({...prev, showEvalBar: !prev.showEvalBar}))}
            else {return}
        }

        return (
            <div className = 'settings-option' onClick = {switchHandler} >{lbl}
                <label className ='switcher'>
                    <input type ='checkbox' checked = {checked} onChange = {switchHandler}></input> 
                    <span className="slider"></span>
                </label>
            </div>
        )
    }

    if (typing && isMobile) return (<></>)

    return (
        <>
        <div className="game-footer-container" ref = {iconRef}> 
            <div className = 'game-footer' title = 'settings' onClick= {settingsHandler}>
                <SettingsSVG opened = {opened}/>
                <label className = {`game-footer-label ${opened? 'active' : ''}`}>Settings</label>
            </div>
            {opened ? 
                <div className="ripple-container toggle-footer">
                    <span ref = {buttonRef} className = 'ripple'></span> 
                </div> : <></>
            }
        </div>

        <div className = 'settings-extended' ref = {settingsRef}>
        {opened ?
            <>
            {noChat ? <Switcher key = 'show evaluation bar' flag = {settings.showEvalBar} lbl = 'show evaluation bar'></Switcher> : <></>}
            <Switcher key = 'show legal moves' flag = {settings.showLegalMoves} lbl = 'show legal moves'></Switcher>
            <Switcher key = 'mark last move' flag = {settings.markLastMove} lbl = 'mark last move'></Switcher>
            <Switcher key = 'sound' flag = {settings.sound} lbl = 'sound'></Switcher>
            {!noChat ? <Switcher key = 'chat' flag = {settings.chat} lbl = 'chat'></Switcher> : <></>}
            </> : <></>
        }   
        </div>
        </> 
    )
}

